    private static final class FailingConnection implements PathlandConnection {
        int attempts;

        @Override
        public void send(byte[] bytes) {
            attempts++;
            throw new RuntimeException("send failed");
        }

        @Override
        public boolean isOpen() {
            return true;
        }
    }
